insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('quinoa', 'quinoa', array[]::text[], 'list', $r$[{"title":"Salade de quinoa","intro":"Du quinoa avec concombre, tomates, feta et herbes, comme un taboulé.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"quinoa salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":250,"unit":"g","have":false},{"name":"feta","plural":"fetas","qty":150,"unit":"g","have":false},{"name":"menthe fraîche","plural":"menthe fraîche","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Rince le quinoa, puis fais-le cuire 12 min à l'eau salée. Égoutte et laisse refroidir.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe le concombre en dés et les tomates en deux.","timer":null},{"text":"Mélange avec le quinoa, la feta émiettée et la menthe ciselée.","timer":null},{"text":"Assaisonne de jus de citron et d'huile d'olive.","timer":null}]},{"title":"Buddha bowl","intro":"Un bol complet et coloré : quinoa, pois chiches rôtis, légumes, avocat et sauce au tahin.","minutes":35,"calories":560,"difficulty":"Facile","imageSearch":"buddha bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"pois chiche","plural":"pois chiches","qty":250,"unit":"g","have":false},{"name":"patate douce","plural":"patates douces","qty":1,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"chou rouge","plural":"choux rouges","qty":0.25,"unit":"","have":false},{"name":"carotte